package uk.ac.ravensbourne.casevault.service;
import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import uk.ac.ravensbourne.casevault.audit.AuditEventType; import uk.ac.ravensbourne.casevault.audit.AuditService; import uk.ac.ravensbourne.casevault.repository.*; import uk.ac.ravensbourne.casevault.security.*;
/** Service-layer approval check prevents managers approving reports they generated (CWE-863). */
@Service public class ReportApprovalService { private final ReportRepository reports; private final UserAccountRepository users; private final CaseAccessService access; private final AuditService audit; public ReportApprovalService(ReportRepository r,UserAccountRepository u,CaseAccessService a,AuditService au){reports=r;users=u;access=a;audit=au;} @Transactional @RequiresCaseAccess public void approve(UserPrincipal p,UUID caseId,UUID reportId){var report=reports.findByIdAndCaseRecordId(reportId,caseId).orElseThrow(CaseNotFoundException::new);access.requireReportApproval(p,caseId,report.getGeneratedBy().getId());report.approve(users.findById(p.id()).orElseThrow(CaseNotFoundException::new));audit.record(p,AuditEventType.REPORT_APPROVED,"REPORT",reportId,"report-approved");} }
